export const BottomBar = () => {
  const data = useFile(state => state.fileData);
  const toggleLiveTransform = useConfig(state => state.toggleLiveTransform);
  const liveTransformEnabled = useConfig(state => state.liveTransformEnabled);
  const error = useFile(state => state.error);
  const setContents = useFile(state => state.setContents);
  const toggleFullscreen = useGraph(state => state.toggleFullscreen);
  const fullscreen = useGraph(state => state.fullscreen);
  const setFormat = useFile(state => state.setFormat);
  const currentFormat = useFile(state => state.format);

  const toggleEditor = () => {
    toggleFullscreen(!fullscreen);
    gaEvent("toggle_fullscreen");
  };

  React.useEffect(() => {
    if (data?.name) window.document.title = `${data.name} | JSON Crack`;
  }, [data]);

  return (
    <StyledBottomBar>
      <StyledLeft>
        <Tooltip label="Close editor" position="bottom" withArrow openDelay={750}>
          <StyledBottomBarItem onClick={toggleEditor} aria-label="close editor">
            <LuPanelLeftClose size={14} />
          </StyledBottomBarItem>
        </Tooltip>
        <StyledBottomBarItem>
          {error ? (
            <Popover width="auto" shadow="md" position="top" withArrow>
              <Popover.Target>
                <Flex align="center" gap={2}>
                  <VscError color="red" />
                  <Text c="red" fw={500} fz="xs">
                    Invalid
                  </Text>
                </Flex>
              </Popover.Target>
              <Popover.Dropdown style={{ pointerEvents: "none" }}>
                <Text size="xs">{error}</Text>
              </Popover.Dropdown>
            </Popover>
          ) : (
            <Flex align="center" gap={2}>
              <VscCheck />
              <Text size="xs">Valid</Text>
            </Flex>
          )}
        </StyledBottomBarItem>
        <StyledBottomBarItem
          onClick={() => {
            toggleLiveTransform(!liveTransformEnabled);
            gaEvent("toggle_live_transform");
          }}
        >
          {liveTransformEnabled ? <VscSync /> : <VscSyncIgnored />}
          <Text fz="xs">Live Transform</Text>
        </StyledBottomBarItem>
        {!liveTransformEnabled && (
          <StyledBottomBarItem onClick={() => setContents({})} disabled={!!error}>
            <VscRunAll />
            Click to Transform
          </StyledBottomBarItem>
        )}
      </StyledLeft>

      <StyledRight>
        <Menu offset={8}>
          <Menu.Target>
            <StyledBottomBarItem>
              <Flex align="center" gap={2}>
                <Text size="xs">{currentFormat?.toUpperCase()}</Text>
                <LuChevronDown size={12} />
              </Flex>
            </StyledBottomBarItem>
          </Menu.Target>
          <Menu.Dropdown>
            {formats.map(format => (
              <Menu.Item
                key={format.value}
                onClick={() => setFormat(format.value)}
                rightSection={currentFormat === format.value && <IoMdCheckmark />}
              >
                {format.label}
              </Menu.Item>
            ))}
          </Menu.Dropdown>
        </Menu>
      </StyledRight>
    </StyledBottomBar>
  );
};

import ReactPDF, { Document, Font, Page, StyleSheet, Text } from "@react-pdf/renderer";
import { i18n } from "next-i18next";
import React from "react";

import View = ReactPDF.View;

const getFontUrlForLanguageCode = (languageCode: string) => {
  switch (languageCode) {
    case "en":
      return ""; // Do not use a custom font for english
    case "zh":
      return "/fonts/SimSun.ttf";
    case "ja":
      return "/fonts/Nasu-Regular.ttf";
    case "ko":
      return "/fonts/NanumMyeongjo-Regular.ttf";
    default:
      return "/fonts/Roboto-Regular.ttf";
  }
};

const getFontUrl = () => getFontUrlForLanguageCode(i18n?.language || "en");

Font.register({
  family: "customFont",
  src: getFontUrl(),
});

const styles = StyleSheet.create({
  page: {
    flexDirection: "column",
    backgroundColor: "#FFFFFF",
    padding: 40,
    wordBreak: "break-all",
  },
  horizontalRule: {
    borderBottomWidth: 0.3,
    borderBottomColor: "#000",
    borderBottomStyle: "solid",
  },
  section: {
    fontSize: 10,
    ...(getFontUrl() == "" ? {} : { fontFamily: "customFont" }),
    marginVertical: 10,
    lineHeight: 1.5,
    wordBreak: "break-all",
    paddingRight: 10,
  },
});

// NOTE: This should only ever be imported dynamically to reduce load times
const MyDocument: React.FC<{
  textSections: string[];
}> = ({ textSections }) => (
  <Document>
    <Page size="A4" style={styles.page}>
      {textSections.map((text, index) => (
        <>
          <Text key={index} style={styles.section}>
            {renderTextLines(text)}
          </Text>
          <HorizontalRule />
        </>
      ))}
    </Page>
  </Document>
);

const HorizontalRule: React.FC = () => <View style={styles.horizontalRule} />;

const renderTextLines = (text: string): React.ReactNode[] => {
  const MAX_LINE_LENGTH = 10;
  const lines: string[] = [];
  let start = 0;
  while (start < text.length) {
    const end = start + MAX_LINE_LENGTH;
    const line: string = text.slice(start, end);
    lines.push(line);
    start = end;
  }
  return lines.map((line: string, index) => (
    <React.Fragment key={index}>
      {line}
      <br />
    </React.Fragment>
  ));
};

export default MyDocument;

import * as monaco from "monaco-editor/editor/editor.api"

type AnyEditor = monaco.editor.IStandaloneCodeEditor | monaco.editor.IStandaloneDiffEditor

interface FoldingRegions {
    length: number
    isCollapsed: (index: number) => boolean
    getStartLineNumber: (index: number) => number
    toRegion: (index: number) => unknown
}

interface FoldingModel {
    textModel: {getLineContent: (line: number) => string}
    regions: FoldingRegions
    toggleCollapseState: (regions: unknown[]) => void
}

export interface EditorActionsContext {
    t: (key: string) => string
    readOnly: boolean
    inline: boolean
    lang?: string
    canFoldFromNavbar: boolean
    onSave: (value?: string) => void
    onExecute: (value?: string) => void
    onConfirm: (value?: string) => void
    autoFold: (shouldFold?: boolean) => void
}

export function registerEditorActions(editor: AnyEditor, ctx: EditorActionsContext) {
    const {KeyCode, KeyMod} = monaco

    if (!ctx.readOnly) {
        editor.addAction({
            id: "kestra-save",
            label: ctx.t("save"),
            keybindings: [KeyMod.CtrlCmd | KeyCode.KeyS],
            contextMenuGroupId: "navigation",
            contextMenuOrder: 1.5,
            run: (e) => ctx.onSave(e.getValue()),
        })
    } else if (ctx.lang === "json") {
        (editor as monaco.editor.IStandaloneCodeEditor).getAction?.("editor.action.formatDocument")?.run()
    }

    editor.addAction({
        id: "moveCursor",
        label: "Move cursor",
        run: (e, args?: {lineNumber: number, column: number}) => {
            if (!args?.lineNumber || !args?.column) return
            e.setPosition({lineNumber: args.lineNumber, column: args.column})
            e.revealPositionInCenter({lineNumber: args.lineNumber, column: args.column})
            e.focus()
        },
    })

    editor.addAction({
        id: "kestra-execute",
        label: ctx.t("execute flow behaviour"),
        keybindings: [KeyMod.CtrlCmd | KeyCode.KeyE],
        contextMenuGroupId: "navigation",
        contextMenuOrder: 1.5,
        run: (e) => ctx.onExecute(e.getValue()),
    })

    editor.addAction({
        id: "confirm",
        label: ctx.t("confirm"),
        keybindings: [KeyMod.CtrlCmd | KeyCode.Enter],
        contextMenuGroupId: "navigation",
        contextMenuOrder: 1.5,
        run: (e) => ctx.onConfirm(e.getValue()),
    })

    if (ctx.inline) {
        editor.addAction({id: "prevent-ctrl-h", label: "Prevent CTRL + H", keybindings: [KeyMod.CtrlCmd | KeyCode.KeyH], run: () => {}})
        editor.addAction({id: "prevent-f1", label: "Prevent F1", keybindings: [KeyCode.F1], run: () => {}})
        if (!ctx.readOnly) {
            editor.addAction({id: "prevent-ctrl-f", label: "Prevent CTRL + F", keybindings: [KeyMod.CtrlCmd | KeyCode.KeyF], run: () => {}})
        }
    }

    if (!ctx.canFoldFromNavbar) return

    editor.addAction({
        id: "fold-multiline",
        label: ctx.t("fold_all_multi_lines"),
        keybindings: [KeyCode.F10],
        contextMenuGroupId: "fold",
        contextMenuOrder: 1.5,
        async run(e) {
            const foldingContrib = e.getContribution("editor.contrib.folding") as unknown as {
                getFoldingModel?: () => Promise<FoldingModel>
            } | null
            const foldingModel = await foldingContrib?.getFoldingModel?.()
            if (!foldingModel) return

            const {textModel, regions} = foldingModel
            const toToggle = []
            for (let i = regions.length - 1; i >= 0; i--) {
                if (regions.isCollapsed(i) === false) {
                    const startLineNumber = regions.getStartLineNumber(i)
                    if (textModel.getLineContent(startLineNumber).trim().endsWith("|")) {
                        toToggle.push(regions.toRegion(i))
                    }
                }
            }
            foldingModel.toggleCollapseState(toToggle)
        },
    })

    if (localStorage.getItem("autofoldTextEditor") === "true") {
        ctx.autoFold(true)
    }
}

import {ref, type Ref} from "vue"
import * as monaco from "monaco-editor/editor/editor.api"

const CONTENT_NODE_POLL_MS = 30

export interface EditorContentWidgetContext {
    codeEditor: () => monaco.editor.IStandaloneCodeEditor | undefined
    editorRoot: Ref<HTMLElement | null | undefined>
}

export function useEditorContentWidget(ctx: EditorContentWidgetContext) {
    const showWidgetContent = ref(false)

    const widgetNode = (() => {
        const node = document.createElement("div")
        node.className = "editor-content-widget"
        const content = document.createElement("div")
        content.className = "editor-content-widget-content"
        node.appendChild(content)
        return node
    })()

    async function waitForWidgetContentNode(): Promise<void> {
        await new Promise(resolve => setTimeout(resolve, CONTENT_NODE_POLL_MS))
        if (document.querySelector(".editor-content-widget-content") === null) {
            return waitForWidgetContentNode()
        }
    }

    async function addContentWidget(widget: {id: string, position: monaco.IPosition, height: number, right: string}) {
        const editor = ctx.codeEditor()
        if (!editor) return

        editor.addContentWidget({
            getId() { return widget.id },
            getPosition() {
                return {
                    position: widget.position,
                    preference: [monaco.editor.ContentWidgetPositionPreference.EXACT],
                }
            },
            getDomNode: () => {
                const content = widgetNode.querySelector(".editor-content-widget-content") as HTMLDivElement
                if (content) content.style.height = widget.height + "rem"
                return widgetNode
            },
            afterRender() {
                const rect = ctx.editorRoot.value!.querySelector(".monaco-scrollable-element")!.getBoundingClientRect()
                widgetNode.style.left = `calc(${rect.width}px - 150px - ${widget.right})`
            },
        })

        await waitForWidgetContentNode()
        showWidgetContent.value = true
    }

    function removeContentWidget(id: string) {
        showWidgetContent.value = false
        const editor = ctx.codeEditor()
        if (!editor) return
        editor.removeContentWidget({
            getId: () => id,
            getPosition() { return {position: {lineNumber: 0, column: 0}, preference: []} },
            getDomNode: () => widgetNode,
        })
    }

    return {showWidgetContent, addContentWidget, removeContentWidget}
}

use crate::app::actions::Effect;
use crate::app::agent_view::ExternalPromptEditorAccess;
use crate::app::app_view::{ActiveView, AppView, VoiceTarget};
use crate::app::external_editor::{
    ATTACHMENT_MESSAGE, PASTE_MESSAGE, PendingEditorRequest, VOICE_MESSAGE, report_prompt_failure,
};

pub(super) fn dispatch_edit_prompt_external(app: &mut AppView) -> Vec<Effect> {
    if app.pending_editor.is_some() {
        return vec![];
    }
    let ActiveView::Agent(agent_id) = app.active_view else {
        return vec![];
    };
    let Some(agent) = app.agents.get(&agent_id) else {
        return vec![];
    };
    let access = agent.external_prompt_editor_access();
    if app.voice_recording_target() == Some(VoiceTarget::Agent(agent_id)) {
        report_prompt_failure(app, agent_id, VOICE_MESSAGE);
        return vec![];
    }
    match access {
        ExternalPromptEditorAccess::OwnedElsewhere => return vec![],
        ExternalPromptEditorAccess::PastePending => {
            report_prompt_failure(app, agent_id, PASTE_MESSAGE);
            return vec![];
        }
        ExternalPromptEditorAccess::Attachments => {
            report_prompt_failure(app, agent_id, ATTACHMENT_MESSAGE);
            return vec![];
        }
        ExternalPromptEditorAccess::Ready => {}
    }

    app.pending_editor = Some(PendingEditorRequest::PromptDraft {
        agent_id,
        original_text: agent.prompt.text().to_owned(),
    });
    vec![]
}

use crossterm::event::{KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use xai_ratatui_textarea::{
    EditBuffer, EditCommand, EditOutcome, SingleLineViewport, classify_key_event,
};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LineEditOutcome {
    Unhandled,
    /// The key was recognized and consumed, but text and cursor stayed unchanged.
    HandledNoChange,
    CursorChanged,
    TextChanged,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct LineEditor {
    buffer: EditBuffer,
}

impl LineEditor {
    pub fn text(&self) -> &str {
        self.buffer.text()
    }

    pub fn cursor_byte(&self) -> usize {
        self.buffer.cursor_byte()
    }

    pub fn set_text(&mut self, text: impl Into<String>) {
        self.buffer = EditBuffer::from_text(sanitize_single_line(text));
    }

    pub fn reset(&mut self) {
        self.buffer = EditBuffer::new();
    }

    /// Test helper; cross-crate consumers (the pager's tests) need it, so it cannot be `#[cfg(test)]`-gated here.
    pub fn set_cursor_byte(&mut self, cursor_byte: usize) -> LineEditOutcome {
        Self::from_edit_outcome(self.buffer.set_cursor_byte(cursor_byte))
    }

    pub fn delete_last_grapheme(&mut self) -> LineEditOutcome {
        let _ = self.buffer.set_cursor_byte(self.buffer.text().len());
        Self::from_edit_outcome(self.buffer.apply(EditCommand::DeleteGraphemeBackward))
    }

    pub fn insert_paste(&mut self, text: &str) -> LineEditOutcome {
        self.insert_paste_with_policy(text, |_| true, usize::MAX)
    }

    pub fn insert_paste_with_policy(
        &mut self,
        text: &str,
        mut allow_insert: impl FnMut(char) -> bool,
        max_chars: usize,
    ) -> LineEditOutcome {
        let cleaned = sanitize_single_line(text);
        let accepted = cleaned
            .chars()
            .filter(|character| allow_insert(*character))
            .take(max_chars)
            .collect::<String>();
        if accepted.is_empty() {
            return LineEditOutcome::HandledNoChange;
        }
        Self::from_edit_outcome(self.buffer.insert_str(&accepted))
    }

    pub fn insert_paste_with_byte_limit(
        &mut self,
        text: &str,
        max_total_bytes: usize,
    ) -> LineEditOutcome {
        let cleaned = sanitize_single_line(text);
        let remaining = max_total_bytes.saturating_sub(self.buffer.text().len());
        let mut accepted_bytes = 0usize;
        let accepted = cleaned
            .chars()
            .take_while(|character| {
                let next = accepted_bytes + character.len_utf8();
                if next > remaining {
                    return false;
                }
                accepted_bytes = next;
                true
            })
            .collect::<String>();
        if accepted.is_empty() {
            return LineEditOutcome::HandledNoChange;
        }
        Self::from_edit_outcome(self.buffer.insert_str(&accepted))
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> LineEditOutcome {
        self.handle_key_with_insert_policy(key, |_| true)
    }

    pub fn handle_key_with_insert_policy(
        &mut self,
        key: &KeyEvent,
        allow_insert: impl FnOnce(char) -> bool,
    ) -> LineEditOutcome {
        if key.kind == KeyEventKind::Release {
            return LineEditOutcome::Unhandled;
        }
        let command = match key {
            KeyEvent {
                code: KeyCode::Home,
                ..
            }
            | KeyEvent {
                code: KeyCode::Left,
                modifiers: KeyModifiers::SUPER,
                ..
            } => Some(EditCommand::MoveLogicalLineStart),
            KeyEvent {
                code: KeyCode::End, ..
            }
            | KeyEvent {
                code: KeyCode::Right,
                modifiers: KeyModifiers::SUPER,
                ..
            } => Some(EditCommand::MoveLogicalLineEnd),
            _ => classify_key_event(key),
        };
        let Some(command) = command else {
            return LineEditOutcome::Unhandled;
        };
        if let EditCommand::Insert(character) = command
            && !allow_insert(character)
        {
            return LineEditOutcome::HandledNoChange;
        }
        Self::from_edit_outcome(self.buffer.apply(command))
    }

    pub fn viewport(&self, width: usize) -> SingleLineViewport {
        self.buffer.single_line_viewport(width)
    }

    fn from_edit_outcome(outcome: EditOutcome) -> LineEditOutcome {
        match outcome {
            EditOutcome::Unchanged => LineEditOutcome::HandledNoChange,
            EditOutcome::CursorOnly => LineEditOutcome::CursorChanged,
            EditOutcome::TextOnly(_) | EditOutcome::TextAndCursor(_) => {
                LineEditOutcome::TextChanged
            }
        }
    }
}

pub fn sanitize_single_line(text: impl Into<String>) -> String {
    let mut text = text.into();
    text.retain(|character| !matches!(character, '\r' | '\n'));
    text
}

#[cfg(test)]
mod tests {
    use super::*;
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

    fn key(code: KeyCode, modifiers: KeyModifiers) -> KeyEvent {
        KeyEvent::new(code, modifiers)
    }

    #[test]
    fn canonical_word_keys_and_legacy_alt_bindings() {
        for event in [
            key(KeyCode::Left, KeyModifiers::ALT),
            key(KeyCode::Char('b'), KeyModifiers::ALT),
            key(KeyCode::Left, KeyModifiers::CONTROL),
        ] {
            let mut editor = LineEditor::default();
            editor.set_text("hello-world");
            assert_eq!(editor.handle_key(&event), LineEditOutcome::CursorChanged);
            assert_eq!(editor.cursor_byte(), "hello-".len());
        }

        let mut editor = LineEditor::default();
        editor.set_text("hello-world");
        assert_eq!(
            editor.handle_key(&key(KeyCode::Backspace, KeyModifiers::ALT)),
            LineEditOutcome::TextChanged
        );
        assert_eq!(editor.text(), "hello-");
    }

    #[test]
    fn home_end_super_and_outcomes() {
        let mut editor = LineEditor::default();
        editor.set_text("abc");
        assert_eq!(
            editor.handle_key(&key(KeyCode::Home, KeyModifiers::NONE)),
            LineEditOutcome::CursorChanged
        );
        assert_eq!(
            editor.handle_key(&key(KeyCode::Left, KeyModifiers::SUPER)),
            LineEditOutcome::HandledNoChange
        );
        assert_eq!(
            editor.handle_key(&key(KeyCode::Right, KeyModifiers::SUPER)),
            LineEditOutcome::CursorChanged
        );
        assert_eq!(
            editor.handle_key(&key(KeyCode::End, KeyModifiers::NONE)),
            LineEditOutcome::HandledNoChange
        );
        assert_eq!(
            editor.handle_key(&key(KeyCode::Esc, KeyModifiers::NONE)),
            LineEditOutcome::Unhandled
        );
    }

    #[test]
    fn ctrl_u_kills_only_to_the_cursor() {
        let mut editor = LineEditor::default();
        editor.set_text("hello world");
        assert_eq!(
            editor.handle_key(&key(KeyCode::Left, KeyModifiers::NONE)),
            LineEditOutcome::CursorChanged
        );
        assert_eq!(
            editor.handle_key(&key(KeyCode::Char('u'), KeyModifiers::CONTROL)),
            LineEditOutcome::TextChanged
        );
        assert_eq!(editor.text(), "d");
        assert_eq!(editor.cursor_byte(), 0);
    }

    #[test]
    fn paste_byte_limit_keeps_whole_characters_at_cursor() {
        let mut editor = LineEditor::default();
        editor.set_text("ab");
        let _ = editor.set_cursor_byte(1);
        assert_eq!(
            editor.insert_paste_with_byte_limit("中x", 5),
            LineEditOutcome::TextChanged
        );
        assert_eq!(editor.text(), "a中b");
        assert_eq!(editor.cursor_byte(), "a中".len());
    }

    #[test]
    fn delete_last_grapheme_ignores_cursor_and_deletes_one_cluster() {
        let mut editor = LineEditor::default();
        editor.set_text("a👩🏽\u{200d}💻");
        let _ = editor.set_cursor_byte(0);
        assert_eq!(editor.delete_last_grapheme(), LineEditOutcome::TextChanged);
        assert_eq!(editor.text(), "a");
        assert_eq!(editor.cursor_byte(), 1);
    }

    #[test]
    fn set_text_sanitizes_and_places_cursor_at_end() {
        let mut editor = LineEditor::default();
        editor.set_text("one\r\ntwo\nthree\rfour");
        assert_eq!(editor.text(), "onetwothreefour");
        assert_eq!(editor.cursor_byte(), editor.text().len());
    }

    #[test]
    fn insert_policy_only_gates_insert_commands() {
        let mut editor = LineEditor::default();
        editor.set_text("ab");
        assert_eq!(
            editor.handle_key_with_insert_policy(
                &key(KeyCode::Char('x'), KeyModifiers::NONE),
                |_| false,
            ),
            LineEditOutcome::HandledNoChange
        );
        assert_eq!(editor.text(), "ab");
        assert_eq!(
            editor
                .handle_key_with_insert_policy(&key(KeyCode::Left, KeyModifiers::NONE), |_| false,),
            LineEditOutcome::CursorChanged
        );

        let mut unrestricted = LineEditor::default();
        assert_eq!(
            unrestricted.handle_key(&key(KeyCode::Char('\u{202e}'), KeyModifiers::NONE)),
            LineEditOutcome::TextChanged
        );
        assert_eq!(unrestricted.text(), "\u{202e}");
    }

    #[test]
    fn viewport_keeps_graphemes_and_cursor_visible() {
        let grapheme = "👩🏽\u{200d}💻";
        let mut editor = LineEditor::default();
        editor.set_text(format!("a{grapheme}b"));
        assert_eq!(
            editor.handle_key(&key(KeyCode::Left, KeyModifiers::NONE)),
            LineEditOutcome::CursorChanged
        );
        let viewport = editor.viewport(3);
        let expected = format!("{grapheme}b");
        assert_eq!(
            editor.text().get(viewport.visible_byte_range.clone()),
            Some(expected.as_str())
        );
        assert_eq!(viewport.cursor_display_column, 2);
    }
}
